def solve(inputs: dict) -> float:
    seed = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    x = seed
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.continued_fraction_numerator:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Initial conditions
    p_prev2 = 1      # p_(-1)
    p_prev1 = terms[0]  # p_0

    # If there's only one term, return it
    if len(terms) == 1:
        return float(p_prev1)

    # Apply recurrence for remaining terms
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

