{"name": "quadratic_map", "code": "def solve(inputs: dict) -> float:
    # Matrix exponentiation for 2x2 matrices
    a, b, c, d = inputs['A'], inputs['B'], inputs['C'], inputs['D']
    mod = inputs['MOD']
    k = inputs['K']

    # Start with identity
    result = [[1, 0], [0, 1]]

    # Base matrix
    base = [[a, b], [c, d]]

    # Binary exponentiation
    while k > 0:
        if k % 2 == 1:
            # Multiply result by base
            new_result = [[0, 0], [0, 0]]
            for i in range(2):
                for j in range(2):
                    for p in range(2):
                        new_result[i][j] = (new_result[i][j] + result[i][p] * base[p][j]) % mod
            result = new_result

        # Square the base
        new_base = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for p in range(2):
                    new_base[i][j] = (new_base[i][j] + base[i][p] * base[p][j]) % mod
        base = new_base
        k //= 2

    # Return sum of entries
    total = sum(sum(row) for row in result)
    return float(total)
